const std::vector<FactoryPreset>& getFactoryPresets()
{
    static const std::vector<FactoryPreset> presets = []
    {
        std::vector<FactoryPreset> v;
        v.reserve ((size_t) numEntries);
        for (int i = 0; i < numEntries; ++i)
        {
            FactoryPreset p;
            p.name = juce::String (entries[i].name);
            p.category = juce::String (entries[i].cat);
            for (int k = 0; k < entries[i].count; ++k)
                p.values.emplace_back (juce::String (entries[i].ids[k]),
                                      entries[i].vals[k]);
            v.push_back (std::move (p));
        }
        return v;
    }();
    return presets;
}
